class Solution {
public:
    vector<int> rearrangeArray(vector<int>& nums) {

        vector <int> ans (nums.size());

        int pos = 0;
        int neg = 1;

        for(int i = 0; i < nums.size(); i++){

            if(nums[i] > 0){
               ans[pos] = nums[i];
                pos += 2;
            }

        }

        for(int i = 0; i < nums.size(); i++){

            if(nums[i] < 0){
               ans[neg] = nums[i];
                neg += 2;
            }

        }

        return ans;

    }
};

